const BINS = [[0, 5], [5, 10], [10, 15], [15, 20], [20, 30], [30, null]];
const s = data.series[0];
const viridis = ['#440154', '#414487', '#2A788E', '#22A884', '#7AD151', '#FDE725'];
if (!s) return { data: [], layout: { annotations: [{ text: 'No data in range', showarrow: false }] } };
const col = (name, i) => (s.fields.find(f => f.name === name) || s.fields[i]).values;
const dir = col('dir', 2), spd = col('speed', 1);
const names = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const counts = BINS.map(() => new Array(16).fill(0));
let n = 0;
for (let i = 0; i < dir.length; i++) {
  const d = dir[i], v = spd[i];
  if (d == null || v == null) continue;
  const sector = Math.round((((d % 360) + 360) % 360) / 22.5) % 16;
  const b = BINS.findIndex(([lo, hi]) => v >= lo && (hi === null || v < hi));
  counts[b][sector]++;
  n++;
}
const label = ([lo, hi]) => (hi === null ? lo + '+' : lo + ' – ' + hi) + ' km/h';
const grid = 'rgba(128,128,128,0.45)';
return {
  data: BINS.map((bin, i) => ({
    type: 'barpolar', name: label(bin),
    theta: names.map((_, k) => k * 22.5), width: 21,
    r: counts[i].map(c => (n ? (100 * c) / n : 0)),
    customdata: names,
    marker: { color: viridis[i], line: { width: 0 } },
    hovertemplate: '%{customdata} · ' + label(bin) + '<br>%{r:.1f}% of readings<extra></extra>',
  })),
  layout: {
    polar: {
      bgcolor: 'rgba(0,0,0,0)', barmode: 'stack',
      angularaxis: { direction: 'clockwise', rotation: 90, thetaunit: 'degrees',
        tickmode: 'array', tickvals: [0, 45, 90, 135, 180, 225, 270, 315],
        ticktext: ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'], tickfont: { size: 12 },
        gridcolor: grid, linecolor: 'rgba(0,0,0,0)', ticks: '' },
      radialaxis: { ticksuffix: '%', angle: 90, tickangle: 90, tickfont: { size: 10 }, nticks: 5,
        gridcolor: grid, griddash: 'dash', showline: false },
    },
    showlegend: true,
    legend: { orientation: 'v', x: 1.05, y: 0.95, font: { size: 11 }, traceorder: 'reversed' },
    margin: { t: 30, b: 30, l: 30, r: 30 },
    paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)',
  },
  config: { displayModeBar: false, responsive: true },
};

